UPDATE ctrl.audit_log
SET status = 'SUCCESS',
    end_time = SYSUTCDATETIME(),
    records_written = @{int(activity('Get Gold Notebook Result').output.properties.exitValue)}
WHERE adf_run_id = '@{pipeline().parameters.adf_run_id}'
  AND table_id = @{pipeline().parameters.table_id};

UPDATE ctrl.audit_log
set status='FAILED',end_time=sysutcdatetime()
where adf_run_id='@{pipeline().parameters.adf_run_id}' and table_id=@{item().table_id}

UPDATE ctrl.audit_log
set status='SUCCESS',end_time=sysutcdatetime(),records_written=@{activity('Bronze To Silver').output.runOutput}
where adf_run_id='@{pipeline().parameters.adf_run_id}' and table_id=@{pipeline().parameters.table_id};

UPDATE ctrl.audit_log
SET status = 'SUCCESS',
    end_time = SYSUTCDATETIME(),
    records_written = @{int(activity('Get Silver Notebook Result').output.properties.exitValue)}
WHERE adf_run_id = '@{pipeline().parameters.adf_run_id}'
  AND table_id = @{pipeline().parameters.table_id};

update ctrl.watermark 
set watermark_value = sysutcdatetime()
where table_id=@{pipeline().parameters.table_id}

query.value:
@concat(
    'SELECT * FROM public.',
    activity('Read Table Details').output.firstRow.source_table_name,
    if(
        equals(
            activity('Read Table Details').output.firstRow.load_type,
            'FULL'
        ),
        '',
        concat(
            ' WHERE ',
            activity('Read Table Details').output.firstRow.watermark_column,
            ' > ',
            '''',
            variables('watermark_value'),
            ''''
        )
    )
)

